const ITEMS={
 energyPotion:{name:'Enerji İksiri',kind:'consumable',color:'#8bd6a6',price:18,description:'60 enerji yeniler. 8 saniye bekleme süresi. Enerjin doluyken harcanmaz.'},
 jelly:{name:'Slime özü',kind:'material',icon:'●',color:'#9dc57d',price:8,description:'Simyada kullanılan yapışkan bir orman özü.'},
 ore:{name:'Demir cevheri',kind:'material',icon:'◆',color:'#abb9c4',price:15,description:'Boran’da kılıç ve zırh güçlendirmede kullanılır.'},
 crystal:{name:'Orman kristali',kind:'material',icon:'✧',color:'#9cd7cc',price:30,description:'İleri kılıç üretimi ve simya tariflerinde kullanılır.'},
 potion:{name:'Can iksiri',kind:'consumable',icon:'♜',color:'#e2a1a0',description:'Kullanıldığında 60 can yeniler. Tam candayken harcanmaz.'},
 thornSeal:{name:'Diken Muhafızı mührü',kind:'trophy',icon:'✺',color:'#c7c18f',price:120,description:'İlk orman boss’undan düşen ganimet. Nara’ya satılabilir.'},
 frostSeal:{name:'Ayaz Hükümdarı mührü',kind:'trophy',icon:'❖',color:'#aed8e4',price:160,description:'İkinci bölgenin boss ganimeti. Nara’ya satılabilir.'},
 stormSeal:{name:'Fırtına Bekçisi mührü',kind:'trophy',icon:'ϟ',color:'#c9b6f1',price:210,description:'Üçüncü bölgenin boss ganimeti. Nara’ya satılabilir.'},
 voidSeal:{name:'Harabe Lordu mührü',kind:'trophy',icon:'◈',color:'#d9a7c6',price:280,description:'Son bölgenin boss ganimeti. Nara’ya satılabilir.'},
 thornCharm:{name:'Kadim Kök Kolyesi',kind:'accessory',icon:'◉',color:'#bacb93',price:180,stats:{damage:5},description:'Kuşanıldığında +5 hasar. Diken Muhafızı’ndan kesin düşer.'},
 frostCharm:{name:'Ayaz Tılsımı',kind:'accessory',icon:'❖',color:'#aedfe9',price:230,stats:{armor:2},description:'Kuşanıldığında alınan hasar −2. Ayaz Hükümdarı ganimeti.'},
 stormCharm:{name:'Fırtına Yüzüğü',kind:'accessory',icon:'ϟ',color:'#d6bcf3',price:290,stats:{damage:8},description:'Kuşanıldığında +8 hasar. Fırtına Bekçisi ganimeti.'},
 voidCharm:{name:'Harabe Kalbi',kind:'accessory',icon:'◈',color:'#e1aacb',price:360,stats:{hp:30},description:'Kuşanıldığında azami can +30. Kuşanmak mevcut canı doldurmaz.'}
};
Object.assign(ITEMS,ADVANCED_ACCESSORIES);
Object.keys(ITEMS).filter(id=>id!=='potion').forEach(id=>{p.inventory[id]=Math.max(0,Math.floor(p.inventory[id]||0));if(ITEMS[id].price)goods[id]={name:ITEMS[id].name,icon:ITEMS[id].icon,price:ITEMS[id].price}});
if(!ITEMS[p.accessory]||!p.inventory[p.accessory])p.accessory=null;
function itemInfo(id){if(id?.startsWith('sword:')){const s=SWORDS[id.slice(6)];return s?{...s,kind:'sword',icon:'⚔',description:s.description+' '+s.effect}:null}return ITEMS[id]||null}
function itemCount(id){if(!itemInfo(id))return 0;return id.startsWith('sword:')?Number(p.swords.includes(id.slice(6))):id==='potion'?p.potions:p.inventory[id]||0}
function accessoryStats(){return ITEMS[p.accessory]?.stats||{}}
const unadornedDamage=damage;damage=function(){return unadornedDamage()+(accessoryStats().damage||0)};
function equipAccessory(id){if(!ITEMS[id]?.stats||!itemCount(id)||activeSwing)return false;const next=p.accessory===id?null:id,oldHp=accessoryStats().hp||0;p.accessory=next;p.maxHp+=(accessoryStats().hp||0)-oldHp;p.hp=Math.min(p.hp,p.maxHp);save();ui();toast(next?ITEMS[next].name+' kuşanıldı.':'Aksesuar çıkarıldı.');return true}
let inventoryFilter='all',selectedInventoryId='sword:'+p.sword;
p.quickSlots=Array.isArray(p.quickSlots)?p.quickSlots.slice(0,5):['sword:'+p.sword,'potion',null,null,null];while(p.quickSlots.length<5)p.quickSlots.push(null);p.quickSlots=p.quickSlots.map(id=>itemInfo(id)?id:null);
function assignQuickSlot(index,id){if(index<0||index>4||!itemInfo(id)||!itemCount(id))return false;p.quickSlots[index]=id;save();renderQuickbar();if($('bag').open)renderInventoryDetail();return true}
function clearQuickSlot(index){p.quickSlots[index]=null;save();renderQuickbar();if($('bag').open)renderInventoryDetail()}
function activateItem(id){if(!itemCount(id)){toast('Bu eşyadan kalmadı.');return false}const info=itemInfo(id);if(info.kind==='sword')return equipSword(id.slice(6));if(id==='potion'){potion();return true}if(info.kind==='accessory')return equipAccessory(id);selectedInventoryId=id;openPanel('bag');toast('Bu eşya bir malzeme veya ganimet; satılabilir ya da üretimde kullanılabilir.');return true}
function activateQuickSlot(index){const id=p.quickSlots[index];if(!id){toast((index+1)+'. slot boş. B ile envanteri aç ve eşya ata.');return false}return activateItem(id)}
function itemIconHTML(id,large=false){const i=itemInfo(id);if(id==='potion')return '<canvas class="item-sword" data-potion-icon width="40" height="64" aria-label="Can iksiri"></canvas>';return id.startsWith('sword:')?`<canvas class="item-sword" data-sword-icon="${id.slice(6)}" width="40" height="64" aria-label="${i.name}"></canvas>`:`<span class="item-glyph ${large?'large':''}" style="color:${i.color}">${i.icon}</span>`}
function paintItemIcons(root){root.querySelectorAll('[data-sword-icon]').forEach(c=>{const g=c.getContext('2d');g.clearRect(0,0,40,64);g.save();g.translate(20,49);g.scale(.65,.65);blade(g,c.dataset.swordIcon,p.swordUpgrades[c.dataset.swordIcon]);g.restore()});root.querySelectorAll('[data-potion-icon]').forEach(c=>{const g=c.getContext('2d');g.clearRect(0,0,40,64);g.fillStyle='#152637';g.fillRect(12,13,16,12);g.fillRect(7,24,26,26);g.fillRect(10,49,20,5);g.fillStyle='#b4d4d5';g.fillRect(14,16,12,11);g.fillRect(10,25,20,24);g.fillStyle='#b96776';g.fillRect(12,32,16,15);g.fillStyle='#e8a2a3';g.fillRect(13,33,4,11);g.fillStyle='#edf4e5';g.fillRect(11,27,3,10);g.fillStyle='#86634d';g.fillRect(12,10,16,6);g.fillStyle='#c9a278';g.fillRect(13,10,13,2)})}
function allOwnedItems(){return[...p.swords.map(id=>'sword:'+id),...(p.potions>0?['potion']:[]),...Object.keys(ITEMS).filter(id=>id!=='potion'&&itemCount(id)>0)]}
function renderQuickbar(){const bar=$('quickbar');if(!bar)return;bar.innerHTML=p.quickSlots.map((id,index)=>{const info=itemInfo(id),count=itemCount(id),equipped=isEquipped(id);return`<button class="quick-slot ${equipped?'equipped':''} ${id&&!count?'depleted':''}" data-quick="${index}" title="${index+1} · ${info?.name||'Boş slot'} · B ile eşya ata" aria-label="${index+1}. slot: ${info?.name||'Boş'}"><kbd>${index+1}</kbd>${info?itemIconHTML(id):'<span class="empty-cross">+</span>'}${info&&info.kind!=='sword'?`<b>${count}</b>`:''}</button>`}).join('');bar.querySelectorAll('[data-quick]').forEach(b=>{const index=Number(b.dataset.quick);b.onclick=()=>{if($('bag').open&&selectedInventoryId)assignQuickSlot(index,selectedInventoryId);else if(!modalOpen())activateQuickSlot(index)};b.oncontextmenu=e=>{e.preventDefault();clearQuickSlot(index)};b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();assignQuickSlot(index,e.dataTransfer.getData('text/plain'))}});paintItemIcons(bar);}
function renderInventory(){const owned=allOwnedItems(),items=owned.filter(id=>inventoryFilter==='all'||itemInfo(id).kind===inventoryFilter);if(!items.includes(selectedInventoryId))selectedInventoryId=items[0]||null;const categories=[['all','Tümü'],['sword','Kılıç'],['accessory','Aksesuar'],['consumable','İksir'],['material','Malzeme'],['trophy','Boss ganimeti']];
 $('bagContents').innerHTML=`<div class="inventory-topline"><span>◆ ${p.gold} altın</span><span>${owned.length} eşya türü · ${p.potions} iksir</span></div><div class="inventory-tabs">${categories.map(([id,name])=>`<button data-filter="${id}" class="${inventoryFilter===id?'selected':''}">${name}</button>`).join('')}</div><div class="bag-layout"><div><div class="bag-grid">${items.map(id=>`<button draggable="true" class="bag-slot ${id===selectedInventoryId?'selected':''}" data-item="${id}" aria-label="${itemInfo(id).name}, ${itemCount(id)} adet" title="${itemInfo(id).name}">${itemIconHTML(id)}<b>${itemCount(id)}</b>${isEquipped(id)?'<em>◆</em>':''}</button>`).join('')+Array.from({length:Math.max(0,28-items.length)},()=>'<span class="bag-slot empty"></span>').join('')}</div><p class="fine">Eşyayı seç; 1–5’e ata veya alttaki slota sürükle. Slottan kaldırmak için sağ tıkla.</p></div><section id="inventoryDetail"></section></div>`;
 $('bagContents').querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{inventoryFilter=b.dataset.filter;renderInventory()});$('bagContents').querySelectorAll('[data-item]').forEach(b=>{b.onclick=()=>{selectedInventoryId=b.dataset.item;renderInventory()};b.ondragstart=e=>{selectedInventoryId=b.dataset.item;e.dataTransfer.setData('text/plain',b.dataset.item)}});paintItemIcons($('bagContents'));renderInventoryDetail();renderQuickbar();}
function renderInventoryDetail(){const id=selectedInventoryId,i=itemInfo(id);if(!i){$('inventoryDetail').innerHTML='<p>Bu kategoride henüz eşyan yok. Orman boss’larından kazandığın mühür ve aksesuarlar burada görünecek.</p>';return}const canUse=['sword','accessory','consumable'].includes(i.kind),equipped=isEquipped(id);
 $('inventoryDetail').innerHTML=`<div class="detail-icon">${itemIconHTML(id,true)}</div><small>${{sword:'SİLAH',accessory:'AKSESUAR',consumable:'TÜKETİLEBİLİR',material:'ÜRETİM MALZEMESİ',trophy:'BOSS GANİMETİ'}[i.kind]}</small><h3 style="color:${i.color}">${i.name}</h3><p>${i.description}</p><p class="fine">Adet: ${itemCount(id)}${i.price?' · Satış: '+i.price+' altın':''}${i.level?' · Gerekli seviye: '+i.level:''}</p>${canUse?`<button id="inventoryUse" ${i.kind==='sword'&&(equipped||p.level<i.level)?'disabled':''}>${i.kind==='consumable'?'Kullan':equipped&&i.kind==='accessory'?'Çıkar':equipped?'Kuşanıldı':'Kuşan'}</button>`:''}<h4>Hızlı slota ata</h4><div class="assign-slots">${p.quickSlots.map((v,n)=>`<button data-assign="${n}" class="${v===id?'selected':''}">${n+1}</button>`).join('')}</div>`;
 if($('inventoryUse'))$('inventoryUse').onclick=()=>{activateItem(id);renderInventory()};$('inventoryDetail').querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>assignQuickSlot(Number(b.dataset.assign),id));paintItemIcons($('inventoryDetail'));}

const BOSS_DATA=[{name:'Diken Muhafızı',seal:'thornSeal',charm:'thornCharm',sword:'ember',color:'#a4b278'},{name:'Ayaz Hükümdarı',seal:'frostSeal',charm:'frostCharm',sword:'frost',color:'#a0ced9'},{name:'Fırtına Bekçisi',seal:'stormSeal',charm:'stormCharm',sword:'storm',color:'#b9a4da'},{name:'Harabe Lordu',seal:'voidSeal',charm:'voidCharm',sword:'eclipse',color:'#ce9cba'}];
p.bossKills=Object.assign({},p.bossKills||{});zones.forEach((z,index)=>{let pos={x:z.x+1450,y:z.y+820};if(!clearSpawn(pos.x,pos.y))pos=spawnPoint(z);enemies.push({...pos,homeX:pos.x,homeY:pos.y,zone:z,rank:index+1,boss:true,bossIndex:index,name:BOSS_DATA[index].name,hp:240+index*75,max:240+index*75,phase:index,dead:0,hit:0})});
function awardBossLoot(e){const d=BOSS_DATA[e.bossIndex];if(!d)return;e.dead=90;p.inventory[d.seal]++;p.inventory[d.charm]++;p.inventory.ore+=3+e.rank;p.inventory.crystal++;p.gold+=80+e.rank*25;xp(100+e.rank*25);p.bossKills[d.seal]=(p.bossKills[d.seal]||0)+1;unlockSword(d.sword);toast(d.name+' yenildi! '+ITEMS[d.charm].name+' ve mühür envanterine eklendi.');log('BOSS GANİMETİ · '+ITEMS[d.charm].name+' / '+ITEMS[d.seal].name);save();ui();}
function drawBoss(e){const d=BOSS_DATA[e.bossIndex],x=e.x,y=e.y,bob=Math.sin(time*2+e.phase)*2;shadow(x,y,38);ctx.strokeStyle=d.color;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(x,y,42,14,0,0,7);ctx.stroke();polygon([[x-34,y-8],[x-30,y-39+bob],[x-18,y-61+bob],[x+17,y-61+bob],[x+34,y-36+bob],[x+37,y-8],[x+22,y+3],[x-23,y+3]],'#253a3e');polygon([[x-27,y-13],[x-25,y-37+bob],[x-15,y-54+bob],[x+14,y-54+bob],[x+26,y-32+bob],[x+28,y-10]],d.color);polygon([[x-28,y-29],[x-46,y-59],[x-24,y-48]],'#83938a');polygon([[x+26,y-31],[x+44,y-62],[x+24,y-48]],'#7f8d8b');rect(x-19,y-35+bob,13,8,'#25383e');rect(x+7,y-35+bob,13,8,'#25383e');rect(x-16,y-33+bob,8,4,'#f3dca1');rect(x+10,y-33+bob,7,4,'#f3dca1');polygon([[x-15,y-20],[x+16,y-20],[x+10,y-12],[x-10,y-12]],'#354a47');rect(x-44,y-77,88,6,'#16272d');rect(x-43,y-76,86*Math.max(0,e.hp/e.max),4,d.color);label('BOSS · '+e.name,x,y-99,d.color,12);}

function serviceButtons(root){root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>serviceAction(b.dataset.action,b.dataset.item))}
function npcTabNames(id){return{merchant:[['trade','Ganimet sat'],['supply','İksir al']],smith:[['upgrade','Güçlendir'],['forge','Kılıç üret']],trainer:[['training','Eğitim'],['bounty','Av ödülü']]}[id]||[]}
let npcActiveTab='';const legacyServiceAction=serviceAction;
serviceAction=function(action,key){const id=$('service').dataset.kind;if(p.area!=='hub'||!$('service').open||nearestService()?.id!==id)return;
 if(action==='sell'||action==='sellAll'){if(id!=='merchant')return;if(action==='sell'){if(!goods[key]||!itemCount(key)||p.accessory===key)return;p.gold+=p.inventory[key]*goods[key].price;p.inventory[key]=0;}else{let total=0;Object.entries(goods).forEach(([k,g])=>{if(k!==p.accessory){total+=(p.inventory[k]||0)*g.price;p.inventory[k]=0}});p.gold+=total;if(total)log('Nara’ya satış · +'+total+' altın');}save();ui();renderService();return}
 if(action==='brewGreater'){if(id!=='alchemist'||p.inventory.thornSeal<1||p.inventory.jelly<4)return;p.inventory.thornSeal--;p.inventory.jelly-=4;p.potions+=5;save();ui();renderService();return}
 const allowed={buy:'merchant',weapon:'smith',armor:'smith',forgeSword:'smith',heal:'healer',brew:'alchemist',train:'trainer',bounty:'trainer',supply:'innkeeper',map:'cartographer',enter:'forest'};if(allowed[action]!==id)return;legacyServiceAction(action,key);renderQuickbar();};
const legacyRenderService=renderService;
renderService=function(){legacyRenderService();const id=$('service').dataset.kind,root=$('serviceBody'),tabs=npcTabNames(id);if(tabs.length&&!tabs.some(([k])=>k===npcActiveTab))npcActiveTab=tabs[0][0];let html='';
 if(id==='merchant'){if(npcActiveTab==='supply')html=`<p>Yola çıkmadan önce hazırlık yap. Çantanda ${p.potions} can iksiri var.</p><div class="shop-row"><span>Can iksiri<small>60 can yeniler · 20 altın</small></span><button data-action="buy" ${p.gold<20?'disabled':''}>1 adet al</button></div>`;else{const sale=Object.entries(goods).filter(([k])=>itemCount(k)>0);html='<p>Malzemelerini ve boss ganimetlerini satabilirsin. Kuşanılmış ekipman satılmaz; önce envanterden çıkar.</p>'+ (sale.length?sale.map(([k,g])=>`<div class="shop-row"><span style="color:${ITEMS[k]?.color||'#ddd'}">${g.icon} ${g.name}<small>${itemCount(k)} adet · Birimi ${g.price} altın${isEquipped(k)?' · KUŞANILMIŞ':''}</small></span><button data-action="sell" data-item="${k}" ${isEquipped(k)?'disabled':''}>Sat · ${itemCount(k)*g.price} ◆</button></div>`).join(''):'<div class="dungeon-info">Satılacak ganimetin yok. Ormanda yaratık ve boss avla.</div>')+`<button data-action="sellAll" ${!sale.some(([k])=>!isEquipped(k))?'disabled':''}>Tüm satılabilir ganimetleri sat</button>`;}}
 if(id==='smith'){if(npcActiveTab==='forge')html=swordCatalogHTML();else html=`<p>Güçlendirme garantili. Kılıç başına + seviyesi ayrı kaydedilir.</p><div class="dungeon-info">Kuşanılmış: ${equippedSword().name} +${p.weapon}<br>Çantanda: ${p.inventory.ore} cevher / ${p.inventory.crystal} kristal</div>`+['weapon','armor'].map(k=>{const n=p[k],cost=60+n*45,ore=2+n;return`<div class="shop-row"><span>${k==='weapon'?'Kılıç':'Zırh'} +${n}<small>${cost} altın + ${ore} cevher · ${k==='weapon'?'+7 hasar':'−2 alınan hasar'}</small></span><button data-action="${k}" ${n>=10||p.gold<cost||p.inventory.ore<ore?'disabled':''}>${n>=10?'Azami seviye':'+ '+(n+1)+' güçlendir'}</button></div>`}).join('');}
 if(id==='alchemist')html=`<p>Luma topladığın ganimetleri iksire dönüştürür. Gerekli malzemeler işlem sırasında harcanır.</p><div class="shop-row"><span>2 can iksiri<small>3 öz (${p.inventory.jelly}) + 1 kristal (${p.inventory.crystal})</small></span><button data-action="brew" ${p.inventory.jelly<3||p.inventory.crystal<1?'disabled':''}>Üret</button></div><div class="shop-row"><span>5 can iksiri<small>1 Diken mührü (${p.inventory.thornSeal}) + 4 öz (${p.inventory.jelly})</small></span><button data-action="brewGreater" ${p.inventory.thornSeal<1||p.inventory.jelly<4?'disabled':''}>Üret</button></div>`;
 if(id==='trainer'){html=npcActiveTab==='training'?`<p>Her eğitim kalıcı +3 hasar verir. Azami 5 kademe.</p><div class="dungeon-info">Eğitim ${p.training} / 5 · +${p.training*3} hasar</div><button data-action="train" ${p.training>=5||p.gold<100+p.training*60?'disabled':''}>${p.training>=5?'Eğitim tamamlandı':'Eğitim al · '+(100+p.training*60)+' altın'}</button>`:`<p>Her 10 yaratık için devriye ödülü al. Boss’lar da sayılır.</p><div class="dungeon-info">${Math.min(10,Math.max(0,p.kills-p.lastBounty))} / 10 yaratık<br>Ödül: 120 altın + 60 temel XP</div><button data-action="bounty" ${p.kills-p.lastBounty<10?'disabled':''}>Ödülü al</button>`;}
 if(id==='cartographer')html='<p>Fısıltılı Orman’ın dört bölgesinde birer boss var. Haritada kırmızı işaretlerle gösterilirler.</p><div class="dungeon-info">Diken Muhafızı → Kök Kolyesi<br>Ayaz Hükümdarı → Ayaz Tılsımı<br>Fırtına Bekçisi → Fırtına Yüzüğü<br>Harabe Lordu → Harabe Kalbi</div><button data-action="map">Haritayı aç</button>';
 if(id==='forest')html='<p>Yaratıklardan malzeme, boss’lardan mühür, aksesuar ve kılıç kazan. Ganimetler doğrudan B envanterine eklenir.</p><div class="dungeon-info">4 bölge / 4 boss · Önerilen seviye 1–6<br>1–5: hızlı slotlar · R: köye dönüş</div><button data-action="enter">Zindana gir →</button>';
 if(html)root.innerHTML=html;if(tabs.length){root.innerHTML='<div class="npc-tabs">'+tabs.map(([k,t])=>`<button data-npc-tab="${k}" class="${k===npcActiveTab?'selected':''}">${t}</button>`).join('')+'</div>'+root.innerHTML;root.querySelectorAll('[data-npc-tab]').forEach(b=>b.onclick=()=>{npcActiveTab=b.dataset.npcTab;renderService()})}serviceButtons(root);};
